<?php
declare(strict_types=1);
use Medbiohim\Http\Request;
use Medbiohim\Http\Response;
use Medbiohim\Http\Router;
use Medbiohim\Middleware\RequireAuth;
use Medbiohim\Middleware\RequireRole;
use Medbiohim\Repositories\UserRepository;
use Medbiohim\Repositories\HomeworkRepository;
use Medbiohim\Services\ExcelScheduleImporter;
use Medbiohim\Services\SupabaseRest;
return static function(Router $r):void{
 $gate=static fn(Request $q):bool=>RequireAuth::handle($q)&&RequireRole::handle($q,['admin']);
 $r->get('/api/v1/admin/users',static function(Request $q,array $p)use($gate):void{if(!$gate($q))return;$s=isset($q->query['q'])?trim((string)$q->query['q']):null;$c=isset($q->query['course'])&&$q->query['course']!==''?(int)$q->query['course']:null;$role=isset($q->query['role'])&&$q->query['role']!==''?(string)$q->query['role']:null;$lim=min(200,max(1,(int)($q->query['limit']??100)));try{Response::success(['items'=>SupabaseRest::listUsers($lim,$s,$c,$role)],$q->requestId);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$q->requestId,503);}});
 $r->get('/api/v1/admin/homeworks',static function(Request $q,array $p)use($gate):void{if(!$gate($q))return;try{Response::success(['items'=>(new HomeworkRepository())->listAllForReview()],$q->requestId);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$q->requestId,503);}});
 $r->post('/api/v1/admin/homeworks',static function(Request $q,array $p)use($gate):void{if(!$gate($q))return;$t=trim((string)$q->json('title',''));if($t===''){Response::error('VALIDATION_ERROR','title is required',$q->requestId,422);return;}try{$row=SupabaseRest::createHomework(['title'=>$t,'description'=>$q->json('description'),'subject_id'=>$q->json('subject_id'),'group_id'=>$q->json('group_id'),'due_at'=>$q->json('due_at'),'created_by'=>$q->user->id]);Response::success(['item'=>$row],$q->requestId,201);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$q->requestId,503);}});
 $r->post('/api/v1/admin/users/{id}/course',static function(Request $q,array $p)use($gate):void{if(!$gate($q))return;$v=$q->json('course_number',null);$c=$v===null?null:(int)$v;if($c!==null&&($c<1||$c>6)){Response::error('VALIDATION_ERROR','course_number must be 1..6 or null',$q->requestId,422);return;}try{Response::success(['user'=>SupabaseRest::setUserCourse($p['id'],$c)],$q->requestId);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$q->requestId,503);}});
 $r->post('/api/v1/admin/users/roles',static function(Request $q,array $p)use($gate):void{if(!$gate($q))return;$uid=trim((string)$q->json('user_id',''));$role=trim((string)$q->json('role',''));$act=trim((string)$q->json('action','assign'));if($uid===''||!in_array($role,['admin','moderator','teacher','student'],true)){Response::error('VALIDATION_ERROR','user_id and valid role required',$q->requestId,422);return;}try{if($act==='revoke'){if($role==='admin'&&$uid===$q->user->id&&SupabaseRest::countRole('admin')<=1){Response::error('LAST_ADMIN','Cannot revoke the last administrator.',$q->requestId,409);return;}$x=SupabaseRest::revokeRole($uid,$role);}else{$x=SupabaseRest::assignRole($uid,$role);}Response::success($x,$q->requestId);}catch(\Throwable $e){Response::error('DB_ERROR',$e->getMessage(),$q->requestId,503);}});
 $r->post('/api/v1/admin/schedule/import',static function(Request $q,array $p)use($gate):void{if(!$gate($q))return;$f=$_FILES['file']??null;if(!is_array($f)||($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){Response::error('VALIDATION_ERROR','Upload .xlsx in multipart field "file".',$q->requestId,422);return;}try{$rows=ExcelScheduleImporter::parse((string)$f['tmp_name']);$gid=trim((string)($_POST['group_id']??''));$sem=$_POST['semester']??null;if($gid==='')throw new \InvalidArgumentException('group_id is required');$subjects=SupabaseRest::listSubjects();$map=[];foreach($subjects as $x)$map[mb_strtolower(trim((string)$x['name']),'UTF-8')]=$x['id'];$entries=[];foreach($rows as $x){$key=mb_strtolower($x['subject'],'UTF-8');$sid=$map[$key]??null;if(!$sid&&$x['subject']!==''){$sid=SupabaseRest::createSubject(['name'=>$x['subject'],'semester'=>$sem===null||$sem===''?null:(int)$sem])['id']??null;$map[$key]=$sid;}$entries[]=array_merge($x,['subject_id'=>$sid]);}$out=SupabaseRest::replaceSchedule(['group_id'=>$gid,'semester'=>$sem===null||$sem===''?null:(int)$sem,'academic_year_id'=>$_POST['academic_year_id']??null,'entries'=>$entries]);Response::success($out,$q->requestId,201);}catch(\InvalidArgumentException $e){Response::error('VALIDATION_ERROR',$e->getMessage(),$q->requestId,422);}catch(\Throwable $e){Response::error('IMPORT_FAILED',$e->getMessage(),$q->requestId,503);}});
};
